const d = msg.payload || {};
const r = Array.isArray(d.resultado) ? d.resultado : [];
if (r.length === 0) { node.warn('resposta sem resultado'); return null; }

const ts = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-');
const paraNumero = s => { const m = String(s).replace(',', '.').match(/[0-9]+(\.[0-9]+)?/); return m ? parseFloat(m[0]) : null; };
const gasoleo = r.filter(x => x.Combustivel === 'Gasóleo simples').map(x => paraNumero(x.Preco)).filter(v => v !== null);
const media = gasoleo.length ? gasoleo.reduce((a, b) => a + b, 0) / gasoleo.length : null;

return [
  {
    filename: 'D:/HermesAssistant/uni/classes/Integração de Sistemas de Informação/trabalhos/TP1/dados/raw/precos-' + ts + '.json',
    payload: JSON.stringify(d)
  },
  {
    topic: 'precos/recolha',
    payload: {
      ts: ts,
      registos: r.length,
      postos: new Set(r.map(x => x.Id)).size,
      gasoleo_postos: gasoleo.length,
      gasoleo_media: media === null ? null : Math.round(media * 1000) / 1000,
      total_na_fonte: r[0].Quantidade || null
    }
  }
];

const p = msg.payload || {};
const media = p.gasoleo_media === null ? 'n/d' : p.gasoleo_media.toFixed(3).replace('.', ',') + ' EUR/L';
msg.payload = 'recolha ' + p.ts + ' | ' + p.registos + ' precos | ' + p.postos + ' postos | gasoleo ' + media;
return msg;
